export type KVValue = string | KVObject;
export type KVObject = { [k: string]: KVValue };

function isObject(v: KVValue | undefined): v is KVObject {
    return typeof v === "object" && v !== null;
}

function deepCloneKV(v: KVValue): KVValue {
    if (typeof v === "string") return v;
    const out: KVObject = {};
    for (const k of Object.keys(v)) {
        out[k] = deepCloneKV(v[k]);
    }
    return out;
}

function splitValues(s: string): string[] {
    const t = s.trim();
    return t ? t.split(/\s+/) : [];
}

function shouldPickByLevel(raw: string, tokens: string[]): boolean {
    if (tokens.length <= 1) return false;
    // Flags like "A | B" should not be treated as per-level values.
    if (raw.includes("|")) return false;
    return true;
}

function pickByLevel(tokens: string[], idx0: number): string {
    if (tokens.length === 0) return "";
    return tokens[Math.min(idx0, tokens.length - 1)];
}

export function expandItemsByLevel(
    rawItems: KVObject,
    baseOrder: string[],
    maxLevelMap:Record<string, number>
): void {
    const newOrder: string[] = [];
    const newItems: KVObject = {};

    for (const baseKey of baseOrder) {
        const base = rawItems[baseKey];
        if (!isObject(base)) continue;

        // 1) 原 item 原样保留
        newOrder.push(baseKey);
        newItems[baseKey] = base;

        const baseAV = base["AbilityValues"];
        if (!isObject(baseAV)) continue;

        const baseAVKeys = Object.keys(baseAV);

        const maxLevel = maxLevelMap[baseKey] ?? 1;
        if (maxLevel <= 1) continue;

        // 2) 生成派生
        for (let lvl = 1; lvl <= maxLevel; lvl++) {
            const key = `${baseKey}_${lvl}`;
            const oldDerived = rawItems[key];

            // 1) 以 base 为唯一权威骨架
            const cloned = deepCloneKV(base) as KVObject;

            cloned["Shop"] = "-1";

            for (const k of Object.keys(cloned)) {
                if (k === "AbilityValues") continue;

                const v = cloned[k];
                if (typeof v !== "string") continue;

                const tokens = splitValues(v);
                if (shouldPickByLevel(v, tokens)) {
                    cloned[k] = pickByLevel(tokens, lvl - 1);
                }
            }

            // 2) 回灌旧派生中“base 不存在的字段”（派生私有字段）
            if (isObject(oldDerived)) {
                for (const k of Object.keys(oldDerived)) {
                    if (!(k in base)) {
                        cloned[k] = deepCloneKV(oldDerived[k]);
                    }
                }
            }

            // AbilityTextureName
            const baseTex = base["AbilityTextureName"];
            if (typeof baseTex === "string") {
                const lvlStr = String(lvl).padStart(2, "0");
                cloned["AbilityTextureName"] = `${baseTex}-${lvlStr}`;
            }

            const baseScript = base["ScriptFile"];
            if (typeof baseScript === "string") {
                // 统一取目录，避免写死 items/
                const lastSlash = baseScript.lastIndexOf("/");
                const dir = lastSlash >= 0 ? baseScript.slice(0, lastSlash + 1) : "";
                cloned["ScriptFile"] = `${dir}${baseKey}_${lvl}.lua`;
            }

            // ---------- AbilityValues（关键修复点） ----------
            const avFinal: KVObject = {};

            // 1) base 是唯一权威：按 base 顺序写入并覆盖所有 base 字段
            for (const field of baseAVKeys) {
                const rawVal = baseAV[field];
                if (typeof rawVal !== "string") continue;

                if (field === "Level") {
                    avFinal[field] = String(lvl);
                } else {
                    const tokens = splitValues(rawVal);
                    avFinal[field] = shouldPickByLevel(rawVal, tokens)
                        ? pickByLevel(tokens, lvl - 1)
                        : rawVal;
                }
            }

            // 2) 旧派生中的“非 base 字段” → 追加到底部（保留）
            if (isObject(oldDerived)) {
                const oldAV = oldDerived["AbilityValues"];
                if (isObject(oldAV)) {
                    for (const k of Object.keys(oldAV)) {
                        // ★ 唯一正确的“新增字段”判定标准 ★
                        if (!baseAVKeys.includes(k)) {
                            avFinal[k] = deepCloneKV(oldAV[k]);
                        }
                    }
                }
            }

            cloned["AbilityValues"] = avFinal;

            newOrder.push(key);
            newItems[key] = cloned;
        }
    }

    // 3) 重建 rawItems 顺序
    for (const k of Object.keys(rawItems)) delete rawItems[k];
    for (const k of newOrder) rawItems[k] = newItems[k];
}

